{
}

static void test_square_1(void)
{
   TEST_ASSERT_EQUAL_UINT64(1ull, square(1));
}

static void test_square_2(void)
{
   TEST_IGNORE();   // delete this line to run test
   TEST_ASSERT_EQUAL_UINT64(2ull, square(2));
}

